static void convert_directive_name_list_clause(OpenMPDirective* dir, const OmpClause* rc, OpenMPClauseKind ck) {
    OpenMPClause* clause = dir->addOpenMPClause(ck, "");
    if (!clause) {
        return;
    }

    int32_t count = roup_clause_directive_list_count(rc);
    if (count < 0) {
        count = 0;
    }

    if (ck == OMPC_absent) {
        auto* absent_clause = static_cast<OpenMPAbsentClause*>(clause);
        for (int32_t i = 0; i < count; ++i) {
            int32_t roup_dir_kind = roup_clause_directive_list_kind_at(rc, i);
            absent_clause->addDirective(mapRoupToOmpparserDirective(roup_dir_kind));
        }
    } else if (ck == OMPC_contains) {
        auto* contains_clause = static_cast<OpenMPContainsClause*>(clause);
        for (int32_t i = 0; i < count; ++i) {
            int32_t roup_dir_kind = roup_clause_directive_list_kind_at(rc, i);
            contains_clause->addDirective(mapRoupToOmpparserDirective(roup_dir_kind));
        }
    } else {
        warn_unsupported_clause(ck);
    }

    if (clause->getClausePosition() == -1) {
        dir->getClausesInOriginalOrder()->push_back(clause);
        clause->setClausePosition(dir->getClausesInOriginalOrder()->size() - 1);
    }
}

static void convert_affinity_clause(OpenMPDirective* dir, const OmpClause* rc) {
    int32_t mod_code = roup_clause_affinity_modifier(rc);
    OpenMPAffinityClauseModifier mod = OMPC_AFFINITY_MODIFIER_unspecified;
    if (mod_code == 1) {
        mod = OMPC_AFFINITY_MODIFIER_iterator;
    }
    if (mod_code < 0 || mod_code > 1) {
        warn_unsupported_clause(OMPC_affinity);
    }

    OpenMPClause* clause = OpenMPAffinityClause::addAffinityClause(dir, mod);
    if (!clause) {
        return;
    }

    std::vector<std::vector<const char*>> iter_defs = collect_affinity_iterators(rc);
    OpenMPAffinityClause* affinity_clause = static_cast<OpenMPAffinityClause*>(clause);
    for (const auto& def : iter_defs) {
        affinity_clause->addIteratorsDefinitionClass(def);
    }
    free_iterator_defs(iter_defs);

    OmpStringList* vars = roup_clause_variables(rc);
    append_variables_to_clause(clause, vars);
    if (vars) {
        roup_string_list_free(vars);
    }
    if (clause->getClausePosition() == -1) {
        dir->getClausesInOriginalOrder()->push_back(clause);
        clause->setClausePosition(dir->getClausesInOriginalOrder()->size() - 1);
    }
}

static void convert_adjust_args_clause(OpenMPDirective* dir, const OmpClause* rc) {
    OpenMPClause* clause = dir->addOpenMPClause(OMPC_adjust_args, "");
    if (!clause) {
        return;
    }

    auto* adjust = static_cast<OpenMPAdjustArgsClause*>(clause);
    int32_t mod_code = roup_clause_adjust_args_modifier(rc);
    OpenMPAdjustArgsModifier mod = OMPC_ADJUST_ARGS_unknown;
    if (mod_code == 1) {
        mod = OMPC_ADJUST_ARGS_need_device_ptr;
    }
    const char* custom_mod = roup_clause_adjust_args_custom_modifier(rc);
    if (custom_mod && custom_mod[0]) {
        adjust->setModifier(OMPC_ADJUST_ARGS_unknown, custom_mod);
    } else {
        adjust->setModifier(mod, "");
    }

    OmpStringList* args = roup_clause_adjust_args_arguments(rc);
    if (args) {
        int32_t len = roup_string_list_len(args);
        for (int32_t i = 0; i < len; ++i) {
            const char* value = roup_string_list_get(args, i);
            if (value) {
                adjust->addArgument(strdup(value));
            }
        }
        roup_string_list_free(args);
    }

    if (clause->getClausePosition() == -1) {
        dir->getClausesInOriginalOrder()->push_back(clause);
        clause->setClausePosition(dir->getClausesInOriginalOrder()->size() - 1);
    }
}

static void convert_doacross_clause(OpenMPDirective* dir, const OmpClause* rc) {
    int kind_code = roup_clause_doacross_kind(rc);
    OpenMPDoacrossClauseType type = OMPC_DOACROSS_TYPE_unknown;
    if (kind_code == 0) {
        type = OMPC_DOACROSS_TYPE_source;
    } else if (kind_code == 1) {
        type = OMPC_DOACROSS_TYPE_sink;
    }

    OpenMPClause* clause = dir->addOpenMPClause(static_cast<int>(OMPC_doacross), static_cast<int>(type));
    if (!clause) {
        return;
    }

    auto* doacross_clause = dynamic_cast<OpenMPDoacrossClause*>(clause);
    OmpStringList* vars = roup_clause_variables(rc);
    if (doacross_clause && vars) {
        int32_t len = roup_string_list_len(vars);
        if (type == OMPC_DOACROSS_TYPE_source) {
            std::string combined;
            for (int32_t i = 0; i < len; ++i) {
                const char* expr = roup_string_list_get(vars, i);
                if (!expr) continue;
                std::string cleaned = trim_paren_padding(expr);
                cleaned = normalize_expression(cleaned.c_str());
                if (!combined.empty()) {
                    combined += ", ";
                }
                combined += cleaned;
            }
            if (!combined.empty()) {
                doacross_clause->setSourceExpression(combined, OMPC_CLAUSE_SEP_space);
            }
        } else {
            for (int32_t i = 0; i < len; ++i) {
                const char* expr = roup_string_list_get(vars, i);
                if (!expr) continue;
                std::string cleaned = trim_paren_padding(expr);
                cleaned = normalize_expression(cleaned.c_str());
                doacross_clause->addSinkArg(cleaned, OMPC_CLAUSE_SEP_comma);
            }
        }
        roup_string_list_free(vars);
    }

    if (clause->getClausePosition() == -1) {
        dir->getClausesInOriginalOrder()->push_back(clause);
        clause->setClausePosition(dir->getClausesInOriginalOrder()->size() - 1);
    }
}

static void convert_linear_clause(OpenMPDirective* dir, const OmpClause* rc) {
    int32_t mod_code = roup_clause_linear_modifier(rc);
    OpenMPLinearClauseModifier mod = mapRoupLinearModifier(mod_code);
    if (mod == OMPC_LINEAR_MODIFIER_unspecified && (mod_code < 0 || mod_code > 2)) {
        warn_unsupported_clause(OMPC_linear);
    }

    const char* step = roup_clause_linear_step(rc);
    std::string step_text = (step && step[0]) ? std::string(step) : std::string();
    if (std::getenv("ROUP_DEBUG_LINEAR") != nullptr) {
        fprintf(stderr, "[linear] modifier=%d step=\"%s\"\n",
                static_cast<int>(mod),
                step_text.c_str());
    }

    OpenMPClause* clause = nullptr;
    OpenMPLinearClause* linear_clause = nullptr;
    if (normalize_clauses_global) {
        auto* existing_list = dir->getClauses(OMPC_linear);
        for (OpenMPClause* existing : *existing_list) {
            auto* lin = static_cast<OpenMPLinearClause*>(existing);
            if (lin->getModifier() == mod &&
                lin->getUserDefinedStep() == step_text) {
                clause = existing;
                linear_clause = lin;
                break;
            }
        }
    }
    if (!clause) {
        clause = OpenMPLinearClause::addLinearClause(dir, mod);
        if (!clause) {
            return;
        }
        linear_clause = static_cast<OpenMPLinearClause*>(clause);
        if (step && step[0]) {
            linear_clause->setUserDefinedStep(step);
        }
        // Modifier means modifier-first syntax (val/ref/uval(variable):step)
        if (mod != OMPC_LINEAR_MODIFIER_unspecified) {
            linear_clause->setModifierFirstSyntax(true);
        }
    }

    OmpStringList* vars = roup_clause_variables(rc);
    append_variables_to_clause(clause, vars);
    if (vars) {
        roup_string_list_free(vars);
    }
    if (clause->getClausePosition() == -1) {
        dir->getClausesInOriginalOrder()->push_back(clause);
        clause->setClausePosition(dir->getClausesInOriginalOrder()->size() - 1);
    }
}

